\documentclass[11pt]{amsart}

\usepackage{amsmath, amssymb, amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\Spec}{\operatorname{Spec_{proof}}}
\newcommand{\Th}{\operatorname{Th}}
\newcommand{\van}{\operatorname{van}}
\newcommand{\rad}{\operatorname{rad}}
\newcommand{\Z}{\mathbb{Z}}
\newcommand{\B}{\mathbb{B}}
\newcommand{\PowR}{\mathcal{P}(R)}

\title{Prime Congruence Spectra: A Zariski Geometry for Semirings, Proofs, and Tropical Algebra}
\author{Aristotle}
\date{June 22, 2026}

\begin{document}

\begin{abstract}
We develop a spectral geometry for arbitrary semirings, taking \emph{congruences}---equivalence relations compatible with addition and multiplication---as the fundamental algebraic objects in place of ideals. To each congruence we associate its \emph{zero class}, the set of elements equivalent to $0$, and prove that zero classes satisfy the ideal axioms. We single out \emph{prime congruences} by the integral-domain law $ab \sim 0 \Rightarrow a \sim 0 \lor b \sim 0$, and define the \emph{proof spectrum} $\Spec(R)$ as the collection of all prime congruences. On this spectrum we define \emph{Zariski-closed sets} $V(S)$ and the \emph{theory operator} $\Th(X)$, and establish: (i) that $V(\cdot)$ satisfies the closed-set axioms of a topology, including $V(\bigcup\mathcal{S}) = \bigcap_S V(S)$; (ii) that $V$ and $\Th$ form a Galois connection, $S \subseteq \Th(X) \Leftrightarrow X \subseteq V(S)$; (iii) that the induced closure operator (the \emph{radical}) is idempotent and that its fixed points are exactly the intersections of prime theories; and (iv) that over \emph{idempotent} semirings---where $x+x=x$, the home of Boolean logic and tropical algebra---addition is the join of a natural order. The construction provides a uniform spectral framework subsuming the prime spectrum of commutative algebra, a provability semantics for proof theory (with $+ = \lor$, $\times = \land$), and a geometry for tropical optimization. All results have been formalized and machine-checked.
\end{abstract}

\maketitle

\section{Introduction}

The prime spectrum $\operatorname{Spec}(R)$ of a commutative ring is the foundation of modern algebraic geometry: its points are prime ideals, its closed sets are vanishing loci of families of ring elements, and the Nullstellensatz correspondence relates algebra to geometry. We ask whether the same edifice can be raised over \emph{semirings}---structures with addition and multiplication but no subtraction---and answer affirmatively.

The motivation is threefold. First, many computationally and logically central structures are semirings with no additive inverses: the Boolean semiring $\B = (\{0,1\}, \lor, \land)$ is the algebra of provability, and the tropical semiring $(\mathbb{R}\cup\{\infty\}, \min, +)$ is the algebra of optimization. Second, over such structures ideals are no longer in bijection with congruences, so a faithful theory must take the congruence as primitive. Third, the resulting geometry yields a clean dictionary between algebraic geometry and proof theory, in which prime congruences are points, Zariski-closed sets are provability loci, and the radical operator computes deductive closure.

Throughout, $R$ denotes a semiring (associative, with $0$ and $1$, distributive, $0$ absorbing). Commutativity is assumed only where noted.

\section{Congruences and zero classes}

\begin{definition}[semiring congruence, \texttt{SRCong}]
A \emph{congruence} on a semiring $R$ is a relation ${\sim}\subseteq R\times R$ that is reflexive, symmetric, transitive, and compatible with the operations:
\[
a \sim b \ \land\ c \sim d \Rightarrow a + c \sim b + d, \qquad
a \sim b \ \land\ c \sim d \Rightarrow ac \sim bd.
\]
Congruences are ordered by inclusion of graphs, $C \le D$ iff $a\sim_C b \Rightarrow a\sim_D b$, making them a preorder.
\end{definition}

\begin{lemma}[scaling, \texttt{mul\_left}, \texttt{mul\_right}]
For a congruence $C$ and $f\in R$: $a\sim b \Rightarrow fa \sim fb$ and $a \sim b \Rightarrow af \sim bf$.
\end{lemma}
\begin{proof}
Combine multiplicative compatibility with reflexivity $f\sim f$.
\end{proof}

\begin{definition}[zero class, \texttt{SRCong.zeroClass}]
The \emph{zero class} of $C$ is $Z(C) = \{\, a\in R : a\sim_C 0\,\}$.
\end{definition}

\begin{proposition}[zero classes are ideals; \texttt{zero\_mem\_zeroClass}, \texttt{zeroClass\_add\_closed}, \texttt{zeroClass\_mul\_absorb}]\label{prop:ideal}
For every congruence $C$: (1) $0\in Z(C)$; (2) $a,b\in Z(C) \Rightarrow a+b\in Z(C)$; (3) $a\in Z(C) \Rightarrow ab\in Z(C)$ for all $b$.
\end{proposition}
\begin{proof}
(1) is reflexivity $0\sim 0$. (2): from $a\sim 0$, $b\sim 0$, additive compatibility gives $a+b\sim 0+0 = 0$. (3): from $a\sim 0$, $b\sim b$, multiplicative compatibility gives $ab\sim 0\cdot b = 0$ by absorption.
\end{proof}

\section{Prime congruences and the proof spectrum}

\begin{definition}[prime congruence, \texttt{PrimeSRCong}]
A congruence $P$ is \emph{prime} if $ab \sim_P 0 \Rightarrow a\sim_P 0 \lor b\sim_P 0$.
\end{definition}

\begin{definition}[proof spectrum, \texttt{ProofSpectrum}]
$\Spec(R)$ is the type of all prime congruences on $R$, ordered by inclusion.
\end{definition}

\begin{proposition}[prime zero classes are prime theories; \texttt{prime\_cong\_zero\_class\_prime\_theory}]
If $P$ is prime then $Z(P)$ is a \emph{prime theory}: closed under the operations of Proposition~\ref{prop:ideal} and satisfying $ab\in Z(P) \Rightarrow a\in Z(P)\lor b\in Z(P)$.
\end{proposition}
\begin{proof}
The integral-domain law for $\sim_P$ is exactly primality for $Z(P)$.
\end{proof}

\begin{proposition}[nondegenerate points; \texttt{nontrivial\_prime\_exists}]
If $R$ is an integral domain, equality is a prime congruence with $Z=\{0\}$, so $\Spec(R)$ contains a nondegenerate point.
\end{proposition}

\section{The Zariski topology}

\begin{definition}[vanishing, \texttt{vanishes}]
$a\in R$ \emph{vanishes} at $P\in\Spec(R)$ if $a\sim_P 0$; write $\van(P,a)$.
\end{definition}

\begin{definition}[Zariski-closed set, \texttt{zariskiClosed}]
For $S\subseteq R$, $\ V(S) = \{\, P\in\Spec(R) : \forall s\in S,\ \van(P,s)\,\}$.
\end{definition}

\begin{definition}[theory of a set of points, \texttt{theoryOfSpec}]
For $X\subseteq\Spec(R)$, $\ \Th(X) = \{\, a\in R : \forall P\in X,\ \van(P,a)\,\}$.
\end{definition}

\begin{theorem}[Zariski closed-set axioms]\label{thm:zariski}
The family $\{V(S):S\subseteq R\}$ satisfies:
\begin{enumerate}
\item \textup{(\texttt{zariskiClosed\_empty\_eq\_univ})} $V(\varnothing) = \Spec(R)$;
\item \textup{(\texttt{zariskiClosed\_union\_eq\_inter})} $V(S\cup T) = V(S)\cap V(T)$;
\item \textup{(\texttt{zariskiClosed\_antiMono})} $S\subseteq T \Rightarrow V(T)\subseteq V(S)$;
\item \textup{(\texttt{zariskiClosed\_iInter})} for any $\mathcal{S}\subseteq\PowR$,
$\ V\!\big(\bigcup\mathcal{S}\big) = \bigcap_{S\in\mathcal{S}} V(S)$.
\end{enumerate}
\end{theorem}
\begin{proof}
(1) The quantifier over $\varnothing$ is vacuous. (2) $P\in V(S\cup T)$ iff every element of $S\cup T$ vanishes at $P$, equivalently every element of $S$ and every element of $T$ vanish. (3) Restricting a universal statement from $T$ to $S\subseteq T$. (4) $P\in V(\bigcup\mathcal{S})$ iff every $s$ in some $S\in\mathcal{S}$ vanishes at $P$, iff for every $S$ every $s\in S$ vanishes, iff $P\in\bigcap_S V(S)$.
\end{proof}

By (1) and (4) the closed sets contain the whole space and are closed under arbitrary intersection; with (2) for finite unions this yields the \emph{Zariski topology} on $\Spec(R)$.

\section{The Galois connection and the radical}

\begin{theorem}[Galois connection; \texttt{galois\_connection\_theory\_variety}]\label{thm:galois}
For all $S\subseteq R$ and $X\subseteq\Spec(R)$,
\[ S \subseteq \Th(X) \quad\Longleftrightarrow\quad X \subseteq V(S). \]
\end{theorem}
\begin{proof}
Both sides unfold to ``$\forall P\in X,\ \forall s\in S,\ \van(P,s)$,'' read in the two quantifier orders.
\end{proof}

The connection induces a closure operator on theories, the \emph{radical} $\rad(T) := \Th(V(T))$.

\begin{theorem}[radical is a closure operator; \texttt{radicalTheory\_idempotent}]
$\rad$ is extensive, monotone, and idempotent: $\rad(\rad(T)) = \rad(T)$.
\end{theorem}

\begin{theorem}[fixed points; \texttt{radical\_fixpoint\_iff\_inter\_primes}]\label{thm:fixpoint}
$\rad(T) = T$ if and only if $T = \bigcap_{P\in V(T)} Z(P)$, i.e. $T$ is an intersection of prime theories.
\end{theorem}
\begin{proof}
Idempotence is the general Galois identity $\Th V \Th V = \Th V$, from $T\subseteq \Th(V(T))$ and $V(\Th(V(T))) = V(T)$. For the fixed-point statement, $\rad(T) = \Th(V(T)) = \bigcap_{P\in V(T)} Z(P)$ by unfolding $\Th$, so $\rad(T)=T$ exactly when $T$ equals this intersection.
\end{proof}

Theorem~\ref{thm:fixpoint} is the structure theorem: the geometrically meaningful theories are exactly the common content of families of prime semantics---the proof-theoretic counterpart of ``radical ideals are intersections of the primes above them.''

\section{Idempotent semirings: order, join, and the tropical bridge}

A semiring is \emph{idempotent} if $x+x=x$ for all $x$. The Boolean and tropical semirings are idempotent.

\begin{theorem}[natural preorder; \texttt{idempotent\_add\_natural\_preorder}]
In an idempotent semiring, $x\le y :\Leftrightarrow x+y = y$ is a preorder.
\end{theorem}
\begin{proof}
Reflexivity is $x+x=x$. Transitivity: $x+y=y$ and $y+z=z$ give $x+z = x+(y+z) = (x+y)+z = y+z = z$.
\end{proof}

\begin{theorem}[addition is join; \texttt{idem\_add\_is\_join}]
In an idempotent commutative semiring, $x+y$ is the least upper bound of $x$ and $y$: $x\le x+y$, $y\le x+y$, and $x\le z \land y\le z \Rightarrow x+y\le z$.
\end{theorem}
\begin{proof}
$x+(x+y) = (x+x)+y = x+y$, so $x\le x+y$; symmetrically for $y$. If $x+z=z$ and $y+z=z$ then $(x+y)+z = x+(y+z) = x+z = z$.
\end{proof}

\begin{proposition}[idempotent multiples; \texttt{idem\_nsmul\_eq}]
In an idempotent additive monoid, $n\cdot x = x$ for $n\ge 1$.
\end{proposition}
\begin{proof}
Induction: $1\cdot x = x$ and $(n+1)\cdot x = n\cdot x + x = x+x = x$.
\end{proof}

Thus the additive structure of an idempotent semiring is a join-semilattice, and the spectral constructions of \S\S3--5 specialize to Boolean logic and tropical algebra.

\section{A worked example: $\Spec(\Z/6\Z)$}

For a commutative ring, congruences coincide with ideals, so $\Spec(R)\cong\operatorname{Spec}(R)$. For $R=\Z/6\Z$ the prime ideals are $(2)$ and $(3)$, giving two points $P_2,P_3$ with $Z(P_2)=\{0,2,4\}$, $Z(P_3)=\{0,3\}$. Then $V(\{2\})=\{P_2\}$, $V(\{3\})=\{P_3\}$, and by Theorem~\ref{thm:zariski}(2)
\[ V(\{2,3\}) = V(\{2\})\cap V(\{3\}) = \varnothing, \]
the geometric content of $6 = 2\times 3$. Finally $\Th(\{P_2,P_3\}) = Z(P_2)\cap Z(P_3) = \{0\}$, the radical of $(0)$, in agreement with Theorem~\ref{thm:fixpoint}. (The prime-congruence definition imposes no properness condition, so the all-collapsing top congruence is also prime; restricting to the two proper points $P_2,P_3$ recovers the classical picture.)

\section{Algorithms}

\textbf{Algorithm A (congruence enumeration).} Given finite operation tables, enumerate set partitions of the carrier and retain those compatible with $+$ and $\times$; cost is governed by the Bell number $B_n$.

\textbf{Algorithm B (prime detection).} For each congruence test $ab\sim 0 \Rightarrow a\sim 0\lor b\sim 0$ over all pairs; cost $O(n^2)$ per congruence.

\textbf{Algorithm C (Galois closure).} Implement $V,\Th$ as set maps, compute $\rad = \Th\circ V$, verify idempotence and Theorem~\ref{thm:fixpoint} against $\bigcap_{P\in V(T)} Z(P)$.

\section{Applications and discussion}

\emph{Proof theory.} Under $+=\lor$, $\times=\land$, a congruence identifies proofs of equal content, $\Spec(R)$ is the space of consistent triviality assignments, $V(S)$ is the provability locus of $S$, emptiness of $V(S)$ is joint inconsistency, and $\rad$ computes deductive closure. \emph{Tropical geometry.} Theorems on idempotence place $\min$-$+$ algebra inside the spectral framework. \emph{Commutative algebra.} For rings the construction reproduces the classical prime spectrum, so the theory is a conservative extension. Commutativity is needed only for the join statement; the topological results hold in full generality.

\section{Future work}

Recorded in full in the package metadata: a quantitative theory of the radical-closure operator; spectral invariants of idempotent semirings; and an analytic dictionary between zero-free regions and density estimates in the companion number-theoretic project.

\section*{Appendix: formalization notes}

Each result corresponds to a machine-checked declaration: \texttt{SRCong}, \texttt{SRCong.zeroClass}, \texttt{SRCong.mul\_left}, \texttt{SRCong.mul\_right}, \texttt{SRCong.zero\_mem\_zeroClass}, \texttt{SRCong.zeroClass\_add\_closed}, \texttt{SRCong.zeroClass\_mul\_absorb}, \texttt{PrimeSRCong}, \texttt{ProofSpectrum}, \texttt{vanishes}, \texttt{zariskiClosed}, \texttt{theoryOfSpec}, \texttt{zariskiClosed\_empty\_eq\_univ}, \texttt{zariskiClosed\_union\_eq\_inter}, \texttt{zariskiClosed\_antiMono}, \texttt{zariskiClosed\_iInter}, \texttt{galois\_connection\_theory\_variety}, \texttt{prime\_cong\_zero\_class\_prime\_theory}, \texttt{radicalTheory\_idempotent}, \texttt{radical\_fixpoint\_iff\_inter\_primes}, \texttt{idempotent\_add\_natural\_preorder}, \texttt{idem\_add\_is\_join}, \texttt{idem\_nsmul\_eq}, \texttt{nontrivial\_prime\_exists}.

\end{document}

