function V(spec, S):  return { i : for all s in S, s in spec[i] }
function Th(spec, X): return { a : for all i in X, a in spec[i] }
function RADICAL(spec, T, carrier): return Th(spec, V(spec, T))
function IS_FIXED(spec, T, carrier): return RADICAL(spec,T,carrier) == T

